using Godot;
using System;
using GArray=Godot.Collections.Array;
using Settings=Godot.Collections.Dictionary;
public partial class ImageWorkspaceOperations
{
    public Resource add_layer(Control owner,string kind)
    {
        var canvas=Canvas(owner);canvas.GrabFocus();var document=Document(owner);var layer=_layers.create(kind,document.Get("canvas_size").AsVector2I());var properties=layer.Get("properties").AsGodotDictionary();if(kind is "text" or "shape"){var dimensions=(canvas.Size/canvas.Get("zoom").AsSingle()*new Vector2(.45f,.3f)).Max(new Vector2(20,20));layer.Set("dimensions",dimensions);layer.Set("position",_canvas.to_document(canvas,canvas.Size*.5f)-dimensions*.5f);if(kind=="text")properties["text_settings"].AsGodotObject().Get("values").AsGodotDictionary()["font_size"]=Math.Max(1,dimensions.Y*.24);}if(kind is "shape" or "gradient" or "path")properties["color"]=owner.Get("color_picker").As<ColorPickerButton>().Color;Action(owner,()=>{document.Get("layers").AsGodotArray().Add(layer);var selected=canvas.Get("selected").AsGodotArray();selected.Clear();selected.Add(layer.Get("id"));});selection_changed(owner);return layer;
    }
    public void add_layer_from_toolbar(Control owner,string kind){add_layer(owner,kind);if(kind=="image")owner.Call("_replace_image");}
    public void show_add_layer(Control owner)
    {
        var popup=new PopupPanel();popup.AddThemeStyleboxOverride("panel",box(new Color("14212e"),new Color("4d8b7e"),12,14));owner.AddChild(popup);var column=new VBoxContainer{CustomMinimumSize=new Vector2(430,330)};column.AddThemeConstantOverride("separation",10);popup.AddChild(column);var heading=new Label{Text="Create a new layer"};heading.AddThemeFontSizeOverride("font_size",19);column.AddChild(heading);var subtitle=new Label{Text="Start editable, then paint, mask, add effects, duplicate, or merge whenever you need.",AutowrapMode=TextServer.AutowrapMode.WordSmart};subtitle.AddThemeColorOverride("font_color",new Color("8fa8bb"));column.AddChild(subtitle);var grid=new GridContainer{Columns=2};grid.AddThemeConstantOverride("h_separation",8);grid.AddThemeConstantOverride("v_separation",8);column.AddChild(grid);
        foreach(var choice in new[]{("Basic / Empty","Transparent pixels for painting and compositing","basic","paint"),("Image","Choose an image from the project","import","image"),("Text","Editable type with system fonts","text","text"),("Shape","Rectangle, ellipse, triangle or custom polygon","shape","shape")}){var card=new Button{Text=choice.Item1+"\n"+choice.Item2,Alignment=HorizontalAlignment.Left,Icon=icon(owner,choice.Item4),ExpandIcon=true,CustomMinimumSize=new Vector2(202,54)};card.AddThemeConstantOverride("icon_max_width",24);grid.AddChild(card);card.Pressed+=()=>create_layer_choice(owner,choice.Item3,popup);}popup.PopupHide+=popup.QueueFree;popup.PopupCentered(new Vector2I(470,390));
    }
    public void create_layer_choice(Control owner,string kind,PopupPanel popup){popup.Hide();if(kind=="import")owner.Call("_choose_import");else add_layer(owner,kind);}
    public void create_at(Control owner,string kind,Rect2 bounds,Vector2[] points)
    {
        if(kind is "crop" or "lasso_crop"){owner.Call("_apply_crop",bounds,points);return;}var document=Document(owner);var canvas=Canvas(owner);
        if(kind=="path")
        {
            if(Geometry2D.TriangulatePolygon(points).Length==0){owner.Get("status").As<Label>().Text="Use at least three non-collinear points without crossing edges.";return;}var target=_documents.layer_for_id(document,canvas.Get("path_layer_id").AsString());if(target==null)return;Action(owner,()=>{var parent=_documents.layer_for_id(document,target.Get("parent_id").AsString());var inverse=parent!=null?_documents.world_transform(document,parent).AffineInverse():Transform2D.Identity;var dimensions=bounds.Size.Max(Vector2.One);target.Set("dimensions",dimensions);target.Set("rotation",0.0);target.Set("position",inverse*bounds.GetCenter()-dimensions*.5f);_layers.set_linear_basis(target,inverse);var properties=target.Get("properties").AsGodotDictionary();properties["shape"]="custom";properties["points"]=points;properties["path_size"]=dimensions;});owner.Call("_set_tool","move");return;
        }
        var layer=_layers.create(kind,document.Get("canvas_size").AsVector2I());layer.Set("position",bounds.Position);layer.Set("dimensions",bounds.Size);if(kind!="text")layer.Get("properties").AsGodotDictionary()["color"]=owner.Get("color_picker").As<ColorPickerButton>().Color;Action(owner,()=>{document.Get("layers").AsGodotArray().Add(layer);var selected=canvas.Get("selected").AsGodotArray();selected.Clear();selected.Add(layer.Get("id"));});owner.Call("_set_tool","move");if(kind=="text"){var input=owner.Get("_text_input").As<TextEdit>();if(GodotObject.IsInstanceValid(input)){input.GrabFocus();input.SelectAll();}}
    }
    public bool prepare_set_tool(Control owner,string id)
    {
        var canvas=Canvas(owner);if(canvas.Get("_material_busy").AsBool())return false;string previous=canvas.Get("tool").AsString();var settings=owner.Get("_paint_tool_settings").AsGodotDictionary();var repair=canvas.Get("repair_tool").As<RefCounted>();if(id!=previous)
        {
            if(previous is "brush" or "fill")settings[previous]=new Settings{["mode"]=canvas.Get("painting_mode"),["color"]=canvas.Get("color"),["material"]=_materials.copy_material(repair.Get("material").As<Resource>()),["strength"]=canvas.Get("material_strength")};if((id is "brush" or "fill")&&settings.ContainsKey(id)){var remembered=settings[id].AsGodotDictionary();canvas.Set("painting_mode",remembered["mode"]);canvas.Set("color",remembered["color"]);owner.Get("color_picker").As<ColorPickerButton>().Color=canvas.Get("color").AsColor();canvas.Set("material_strength",remembered["strength"]);repair.Set("material",_materials.copy_material(remembered["material"].As<Resource>()));var document=owner.Get("document").As<Resource>();var template=document!=null&&document.Get("live_edit_enabled").AsBool()?_documents.live_material_for_id(document,document.Get("active_live_material_id").AsString()):null;if(canvas.Get("painting_mode").AsString()=="material"&&template!=null)repair.Set("material",_materials.copy_material(template.Get("material").As<Resource>()));}
        }
        if(repair.Get("active").AsBool())_repair.finish(repair);return true;
    }
    public void complete_set_tool(Control owner,string id)
    {
        var canvas=Canvas(owner);var warp=canvas.Get("warp_tool").As<RefCounted>();if(warp.Get("active").AsBool())_warp.finish(warp);if(canvas.Get("_drag").AsString()=="object_preview"&&canvas.Get("_smart_ready").AsBool())_canvas.commit_object_selection(canvas);canvas.GrabFocus();_canvas.cancel_gesture(canvas);if(id is "crop" or "lasso_crop"){canvas.Set("tool","pixel_select");canvas.Set("pixel_mode",id);}else{canvas.Set("tool",id);if(id=="pixel_select"&&(canvas.Get("pixel_mode").AsString() is "crop" or "lasso_crop"))canvas.Set("pixel_mode","brush");}_canvas.sync_pixel_selection(canvas);if(canvas.Get("tool").AsString()=="pixel_select"&&(canvas.Get("pixel_mode").AsString() is not ("crop" or "lasso_crop")))owner.Call("_prepare_pixel_selection");if(id is "brush" or "eraser" or "fill"){if(canvas.Get("selected").AsGodotArray().Count==0)add_layer(owner,"basic");else{var main=main_layer(owner);if(main!=null&&(main.Get("kind").AsString() is not ("image" or "paint" or "basic")))owner.Call("rasterize_selected");}}owner.Call("_refresh_context");foreach(var pair in owner.Get("tool_buttons").AsGodotDictionary())pair.Value.As<Button>().SetPressedNoSignal(pair.Key.AsString()==canvas.Get("tool").AsString());owner.Get("status").As<Label>().Text=tool_hint(owner);canvas.QueueRedraw();
    }
    public string tool_hint(Control owner)
    {
        var canvas=Canvas(owner);string tool=canvas.Get("tool").AsString(),mode=canvas.Get("pixel_mode").AsString();if(tool=="warp")return canvas.Get("warp_tool").AsGodotObject().Get("mode").AsString()=="mesh"?"Drag points to deform · Shift+wheel: radius · Shift-click: select mesh points · Esc: cancel":"Drag to deform · Shift+wheel: size · Shift-click: select mesh points · Ctrl-click pin: lock · Right-click pin: delete · Esc: cancel";if(tool=="repair")return "Drag: repair pixels · Alt-click / drag: sample · Shift+wheel: size · Space: pan · Esc: cancel";if(tool=="pixel_select"&&(mode is "crop" or "lasso_crop"))return "Drag a crop region · Release applies · Right-click / Esc cancels";if(tool=="pixel_select"&&canvas.Get("pixel_box_select").AsBool()&&(mode is "brush" or "erase"))return "Drag: box select · Shift-drag: lasso select · Ctrl: subtract · Esc: cancel";return tool switch{"move"=>"Drag to move · Ctrl toggles snap · Shift constrains · Alt-drag duplicates · Space pans · Wheel zooms","brush"=>"Ctrl: erase · Shift+wheel: size · "+(canvas.Get("brush_type").AsString()=="stroke_correct"?"Alt+wheel: scale · ":"")+"Shift/Q/O: line/curve/circle · 0–9: presets · Esc: cancel","eraser"=>"Erase on selected layer · Shift+wheel: size · [ / ] brush size · Esc cancels","path"=>"Click adds points · Enter closes polygon · Esc cancels","pixel_select"=>"Ctrl: subtract pixels · Shift+wheel: size / fill threshold · Ctrl+Z undoes · Copy / Delete / Extract","fill"=>"Click: fill · Ctrl+click: erase region · Shift+wheel: threshold · Ctrl+Z undoes","lasso_crop"=>"Draw around the crop · Release applies · Right-click / Esc cancels","shape"=>"Drag to create a shape · Edit fill, stroke, and corners in Properties","text"=>"Click to add text · Double-click existing text to edit","crop"=>"Drag a crop region · Right-click / Esc cancels · Choose extract, copy, or remove above",_=>"Space pans · Wheel zooms · Ctrl+K searches actions"};
    }
    public void tool_section(Control owner,Node rail,string caption,GArray entries)
    {
        var panel=new PanelContainer{Name=caption.Capitalize()+"Tools"};panel.AddThemeStyleboxOverride("panel",box(new Color("15232d"),new Color("2b414d"),6,3));rail.AddChild(panel);var column=new VBoxContainer();column.AddThemeConstantOverride("separation",3);panel.AddChild(column);var label=new Label{Text=caption,HorizontalAlignment=HorizontalAlignment.Center};label.AddThemeFontSizeOverride("font_size",8);label.AddThemeColorOverride("font_color",new Color("85a4b1"));column.AddChild(label);var buttons=owner.Get("tool_buttons").AsGodotDictionary();foreach(var value in entries){var entry=value.AsGodotArray();string id=entry[0].AsString();var control=button(owner,column,"",Callable.From(()=>owner.Call("_set_tool",id)),entry[1].AsString(),id=="pixel_select"?"mask":id);control.CustomMinimumSize=new Vector2(34,33);control.ToggleMode=true;buttons[id]=control;}
    }
